def comps_of(g,val=5):
    H,W=len(g),len(g[0]); seen=set(); res=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]==val and (r,c) not in seen:
                st=[(r,c)]; seen.add((r,c)); comp=[]
                while st:
                    x,y=st.pop(); comp.append((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=x+dx,y+dy
                        if 0<=a<H and 0<=b<W and g[a][b]==val and (a,b) not in seen:
                            seen.add((a,b)); st.append((a,b))
                res.append(comp)
    return res

def f(g):
    H,W=len(g),len(g[0])
    out=[r[:] for r in g]
    comps=comps_of(g); cc=comps[0]
    rs=[p[0] for p in cc]; cs=[p[1] for p in cc]
    r0,r1,lft,rgt=min(rs),max(rs),min(cs),max(cs)
    # filled by flood from border (enclosed holes -> 2)
    import collections
    reach=[[False]*W for _ in range(H)]; q=collections.deque()
    for a in range(H):
        for b in (0,W-1):
            if g[a][b]==0 and not reach[a][b]: reach[a][b]=True; q.append((a,b))
    for b in range(W):
        for a in (0,H-1):
            if g[a][b]==0 and not reach[a][b]: reach[a][b]=True; q.append((a,b))
    while q:
        x,y=q.popleft()
        for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
            a,b=x+dx,y+dy
            if 0<=a<H and 0<=b<W and g[a][b]==0 and not reach[a][b]:
                reach[a][b]=True; q.append((a,b))
    for r,c in [(a,b) for a in range(H) for b in range(W) if g[a][b]==0 and not reach[a][b]]:
        out[r][c]=2
    # top border processing
    gaps=[c for c in range(lft,rgt+1) if g[r0][c]==0 and lft<c<rgt and g[r0][c-1]==5 and g[r0][c+1]==5]
    if not gaps: return out
    cg=sum(cs)/len(cs)   # centroid column
    def dist(c): return abs(c-cg)
    emit=max(gaps,key=dist)
    s=(-1,1)[emit>cg]
    q=emit+s
    while 0<=q<W:
        out[r0-1][q]=2; q+=s
    return out

